  if (i < uri.length && uri[i] === '?') {
    i++
    const queryEnd = uri.substring(i).indexOf('#')
    if (queryEnd === -1) {
      query = uri.substring(i)
      i = uri.length
    } else {
      query = uri.substring(i, i + queryEnd)
      i += queryEnd
    }
  }

  // Parse fragment: optional, starts with '#'
