const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

function asciiLower(text) {
  let out = ''
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i)
    out += code >= 65 && code <= 90 ? String.fromCharCode(code + 32) : text[i]
  }
  return out
}

export function parseUri(uri) {
  let scheme
  let authority
  let path
  let query
  let fragment
  let i = 0

  const delim = uri.search(/[:/?#]/)
  if (delim !== -1 && uri[delim] === ':' && delim > 0) {
    scheme = uri.slice(0, delim)
    i = delim + 1
  }

  if (uri.startsWith('//', i)) {
    i += 2
    const rest = uri.slice(i)
    const end = rest.search(/[/?#]/)
