#!/usr/bin/env node

import { readFileSync } from 'node:fs'

/**
 * Parse a URI reference into its components according to RFC 3986.
 * Returns { scheme, authority, path, query, fragment }
 * An absent component is undefined; an empty component is an empty string.
 */
function parseUri(uri) {
  let scheme
  let authority
  let path
  let query
  let fragment

  let i = 0

  // Parse scheme: optional, runs to first ':' if no '/', '?', '#' before it
  const schemeEnd = uri.search(/[:/?#]/)
  if (schemeEnd !== -1 && uri[schemeEnd] === ':') {
    scheme = uri.substring(0, schemeEnd)
    i = schemeEnd + 1
  }

  // Parse authority: optional, introduced by '//' and running to next '/', '?', or '#'
  if (i + 1 < uri.length && uri[i] === '/' && uri[i + 1] === '/') {
    i += 2
    const authEnd = uri.substring(i).search(/[/?#]/)
    if (authEnd === -1) {
      authority = uri.substring(i)
      i = uri.length
    } else {
      authority = uri.substring(i, i + authEnd)
      i += authEnd
    }
  }

  // Parse path: runs to next '?' or '#'
  const pathEnd = uri.substring(i).search(/[?#]/)
  if (pathEnd === -1) {
    path = uri.substring(i)
    i = uri.length
  } else {
    path = uri.substring(i, i + pathEnd)
    i += pathEnd
  }

  // Parse query: optional, starts with '?' and runs to '#'
  if (i < uri.length && uri[i] === '?') {
    i++
    const queryEnd = uri.substring(i).indexOf('#')
    if (queryEnd === -1) {
      query = uri.substring(i)
      i = uri.length
    } else {
      query = uri.substring(i, i + queryEnd)
      i += queryEnd
    }
  }

  // Parse fragment: optional, starts with '#'
  if (i < uri.length && uri[i] === '#') {
    i++
    fragment = uri.substring(i)
    i = uri.length
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Reconstruct a URI from its components.
 */
function reconstructUri(uri) {
  let result = ''
  if (uri.scheme !== undefined) result += uri.scheme + ':'
  if (uri.authority !== undefined) result += '//' + uri.authority
  result += uri.path
  if (uri.query !== undefined) result += '?' + uri.query
  if (uri.fragment !== undefined) result += '#' + uri.fragment
  return result
}

/**
 * Check if a character is unreserved (A-Z, a-z, 0-9, -, ., _, ~)
 */
function isUnreserved(ch) {
  const code = ch.charCodeAt(0)
  return (code >= 65 && code <= 90) ||   // A-Z
         (code >= 97 && code <= 122) ||  // a-z
         (code >= 48 && code <= 57) ||   // 0-9
         ch === '-' || ch === '.' || ch === '_' || ch === '~'
}

/**
 * Normalize percent-encodings in a component.
 * Uppercase hex digits and decode unreserved characters.
 * Returns { value, error } where error is null or an error message.
 */
function normalizePercentEncoding(component, componentName) {
  if (component === undefined) return { value: undefined, error: null }

  let result = ''
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        return { value: null, error: `the ${componentName} has a truncated percent-encoding` }
      }
      const hex = component.substring(i + 1, i + 3)
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
        return { value: null, error: `the ${componentName} has a truncated percent-encoding` }
      }
      const charCode = parseInt(hex, 16)
      const char = String.fromCharCode(charCode)
      if (isUnreserved(char)) {
        result += char
      } else {
        result += '%' + hex.toUpperCase()
      }
      i += 2
    } else {
      result += component[i]
    }
  }
  return { value: result, error: null }
}

/**
 * Parse an authority into userinfo, host, and port.
 */
function parseAuthority(authority) {
  if (authority === undefined) return { userinfo: undefined, host: undefined, port: undefined }

  let userinfo
  let host
  let port

  // Find the last '@' for userinfo
  const lastAt = authority.lastIndexOf('@')
  if (lastAt !== -1) {
    userinfo = authority.substring(0, lastAt)
    authority = authority.substring(lastAt + 1)
  }

  // Find the port: everything after the first ':' after the last ']'
  const lastBracket = authority.lastIndexOf(']')
  let colonIndex = -1
  if (lastBracket === -1) {
    colonIndex = authority.indexOf(':')
  } else {
    colonIndex = authority.indexOf(':', lastBracket)
  }

  if (colonIndex !== -1) {
    host = authority.substring(0, colonIndex)
    port = authority.substring(colonIndex + 1)
  } else {
    host = authority
  }

  return { userinfo, host, port }
}

/**
 * Reconstruct an authority from its components.
 */
function reconstructAuthority(userinfo, host, port) {
  let result = ''
  if (userinfo !== undefined) result += userinfo + '@'
  result += host
  if (port !== undefined) result += ':' + port
  return result
}

/**
 * Get the default port for a scheme.
 */
function getDefaultPort(scheme) {
  if (scheme === undefined) return undefined
  const lower = scheme.toLowerCase()
  if (lower === 'http' || lower === 'ws') return 80
  if (lower === 'https' || lower === 'wss') return 443
  if (lower === 'ftp') return 21
  return undefined
}

/**
 * Remove dot segments from a path according to RFC 3986 section 5.2.4.
 */
function removeDotSegments(path) {
  const input = path
  const output = []

  let i = 0
  while (i < input.length) {
    // A: If input starts with "../" or "./" 
    if (input.substring(i, i + 3) === '../') {
      i += 3
    } else if (input.substring(i, i + 2) === './') {
      i += 2
    }
    // B: If input starts with "/./" or "/."
    else if (input.substring(i, i + 3) === '/./') {
      i += 2  // Move to next '/'
    } else if (input.substring(i) === '/.') {
      i += 1  // Move to '/'
      input = input.substring(0, i) + '/'  // Replace with '/'
    }
    // C: If input starts with "/../" or "/.."
    else if (input.substring(i, i + 4) === '/../') {
      i += 3  // Move to next '/'
      if (output.length > 0) output.pop()
    } else if (input.substring(i) === '/..') {
      i += 2  // Move to '/'
      input = input.substring(0, i) + '/'  // Replace with '/'
      if (output.length > 0) output.pop()
    }
    // D: If input is just "." or ".."
    else if (input.substring(i) === '.' || input.substring(i) === '..') {
      i = input.length
    }
    // E: Move first path segment to output
    else {
      let nextSlash = input.indexOf('/', i + 1)
      if (nextSlash === -1) nextSlash = input.length
      output.push(input.substring(i, nextSlash))
      i = nextSlash
    }
  }

  return output.join('')
}

/**
 * Normalize a URI.
 */
function normalizeUri(uriStr) {
  const uri = parseUri(uriStr)

  // Lowercase scheme
  if (uri.scheme !== undefined) {
    uri.scheme = uri.scheme.toLowerCase()
  }

  // Normalize percent-encodings in userinfo (if in authority)
  if (uri.authority !== undefined) {
    const { userinfo, host, port } = parseAuthority(uri.authority)

    // Normalize userinfo
    if (userinfo !== undefined) {
      const { value, error } = normalizePercentEncoding(userinfo, 'userinfo')
      if (error) return { error, normalized: null }
    }

    // Normalize host percent-encoding (but lowercase it)
    if (host !== undefined) {
      const { value: normalizedHost, error } = normalizePercentEncoding(host, 'host')
      if (error) return { error, normalized: null }
      uri.authority = reconstructAuthority(userinfo, normalizedHost.toLowerCase(), port)
    }
  }

  // Normalize percent-encodings in path
  const { value: normalizedPath, error: pathError } = normalizePercentEncoding(uri.path, 'path')
  if (pathError) return { error: pathError, normalized: null }
  uri.path = normalizedPath

  // Normalize percent-encodings in query
  if (uri.query !== undefined) {
    const { value: normalizedQuery, error: queryError } = normalizePercentEncoding(uri.query, 'query')
    if (queryError) return { error: queryError, normalized: null }
    uri.query = normalizedQuery
  }

  // Normalize percent-encodings in fragment
  if (uri.fragment !== undefined) {
    const { value: normalizedFragment, error: fragmentError } = normalizePercentEncoding(uri.fragment, 'fragment')
    if (fragmentError) return { error: fragmentError, normalized: null }
    uri.fragment = normalizedFragment
  }

  // Drop default port
  if (uri.authority !== undefined) {
    const { userinfo, host, port } = parseAuthority(uri.authority)
    if (port !== undefined) {
      const defaultPort = getDefaultPort(uri.scheme)
      if (port === '' || (defaultPort !== undefined && port === String(defaultPort))) {
        uri.authority = reconstructAuthority(userinfo, host, undefined)
      }
    }
  }

  // Remove dot segments from path
  uri.path = removeDotSegments(uri.path)

  // If authority is present and path is empty, make path '/'
  if (uri.authority !== undefined && uri.path === '') {
    uri.path = '/'
  }

  return { error: null, normalized: reconstructUri(uri) }
}

/**
 * Merge a relative path with a base path.
 */
function mergePaths(basePath, refPath, baseAuthority) {
  if (baseAuthority !== undefined && basePath === '') {
    // Base has authority and empty path
    return '/' + refPath
  }

  // Keep everything of the base path up to and including its last '/'
  const lastSlash = basePath.lastIndexOf('/')
  if (lastSlash === -1) {
    return refPath
  }

  return basePath.substring(0, lastSlash + 1) + refPath
}

/**
 * Resolve a reference against a base URI.
 */
function resolveUri(baseStr, refStr) {
  const base = parseUri(baseStr)
  const ref = parseUri(refStr)

  let target = {}

  // If reference has a scheme, it's used as-is
  if (ref.scheme !== undefined) {
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    // Reference doesn't have a scheme
    if (ref.authority !== undefined) {
      // Reference has authority, use base's scheme
      target.scheme = base.scheme
      target.authority = ref.authority
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      // Reference doesn't have authority
      if (ref.path === '') {
        // Reference has empty path
        target.path = base.path
        if (ref.query !== undefined) {
          target.query = ref.query
        } else {
          target.query = base.query
        }
      } else {
        // Reference has non-empty path
        if (ref.path.startsWith('/')) {
          target.path = removeDotSegments(ref.path)
        } else {
          // Merge paths
          target.path = mergePaths(base.path, ref.path, base.authority)
          target.path = removeDotSegments(target.path)
        }
        target.query = ref.query
      }
      target.authority = base.authority
    }
    target.scheme = base.scheme
  }

  target.fragment = ref.fragment

  // Normalize the result
  const normalized = normalizeUri(reconstructUri(target))
  return normalized
}

/**
 * Main CLI logic
 */
async function main() {
  const args = process.argv.slice(2)

  // Check arguments
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read stdin
  const input = readFileSync(0, 'utf8')

  // Handle empty input
  if (input.length === 0) {
    process.exit(0)
  }

  const lines = input.split('\n')

  // Drop empty tail if input ends with newline
  if (input[input.length - 1] === '\n') {
    lines.pop()
  }

  let lineNum = 0
  for (const line of lines) {
    lineNum++

    if (mode === 'normalize') {
      const result = normalizeUri(line)
      if (result.error) {
        process.stderr.write(`error: line ${lineNum}: ${result.error}\n`)
        process.exit(2)
      }
      process.stdout.write(result.normalized + '\n')
    } else {
      // mode === 'resolve'
      const spaceIndex = line.indexOf(' ')
      if (spaceIndex === -1) {
        process.stderr.write(`error: line ${lineNum}: expected a base and a reference\n`)
        process.exit(2)
      }

      const baseStr = line.substring(0, spaceIndex)
      const refStr = line.substring(spaceIndex + 1)

      // Check if base has a scheme
      const baseUri = parseUri(baseStr)
      if (baseUri.scheme === undefined) {
        process.stderr.write(`error: line ${lineNum}: the base has no scheme\n`)
        process.exit(2)
      }

      const result = resolveUri(baseStr, refStr)
      if (result.error) {
        process.stderr.write(`error: line ${lineNum}: ${result.error}\n`)
        process.exit(2)
      }
      process.stdout.write(result.normalized + '\n')
    }
  }

  process.exit(0)
}

main()

